exercises.solutionCode:
import React, { useState } from 'react';

const LikeButton = ({ initialLikes = 10, onLikeApi }) => {
    const [likes, setLikes] = useState(initialLikes);
    const [isLiked, setIsLiked] = useState(false);

    const handleLike = async () => {
        const prevLikes = likes;
        const prevLiked = isLiked;

        // Optimistic update
        setLikes(prev => prevLiked ? prev - 1 : prev + 1);
        setIsLiked(!prevLiked);

        try {
            await onLikeApi(!prevLiked);
        } catch (error) {
            // Rollback on failure
            setLikes(prevLikes);
            setIsLiked(prevLiked);
            console.error('Like failed, rolled back state.');
        }
    };

    return (
        <button onClick={handleLike} className={isLiked ? 'liked' : ''}>
            {isLiked ? '♥ Liked' : '♡ Like'} ({likes})
        </button>
    );
};

export default LikeButton;

import React, { createContext, useContext, useReducer, useEffect } from 'react';

const CartContext = createContext();

const cartReducer = (state, action) => {
    switch (action.type) {
        case 'ADD_ITEM': {
            const existingIndex = state.findIndex(item => item.id === action.payload.id);
            if (existingIndex > -1) {
                const updated = [...state];
                updated[existingIndex].qty += 1;
                return updated;
            }
            return [...state, { ...action.payload, qty: 1 }];
        }
        case 'REMOVE_ITEM':
            return state.filter(item => item.id !== action.payload);
        case 'CLEAR_CART':
            return [];
        default:
            return state;
    }
};

export const CartProvider = ({ children }) => {
    const [cart, dispatch] = useReducer(cartReducer, [], () => {
        const saved = localStorage.getItem('bytecode_cart');
        return saved ? JSON.parse(saved) : [];
    });

    useEffect(() => {
        localStorage.setItem('bytecode_cart', JSON.stringify(cart));
    }, [cart]);

    const totalCost = cart.reduce((sum, item) => sum + (item.price * item.qty), 0);

    return (
        <CartContext.Provider value={{ cart, dispatch, totalCost }}>
            {children}
        </CartContext.Provider>
    );
};

export const useCart = () => useContext(CartContext);
